using Decont;using Xunit;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using System.Net;using System.Net.Http.Json;using System.Text.Json;
namespace Decont.Tests;
public class ConfigurationDraftTests {
 static async Task<HttpClient> Login(Factory f,string name){var c=f.CreateClient(new(){HandleCookies=true,AllowAutoRedirect=false});var token=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",token.GetProperty("token").GetString());Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{username=name,password="Valid-test-Password1!"})).StatusCode);token=await c.GetFromJsonAsync<JsonElement>("/api/auth/csrf");c.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");c.DefaultRequestHeaders.Add("X-CSRF-TOKEN",token.GetProperty("token").GetString());return c;}
 static void Key(HttpClient c){c.DefaultRequestHeaders.Remove("Idempotency-Key");c.DefaultRequestHeaders.Add("Idempotency-Key",Guid.NewGuid().ToString());}
 [Fact]public async Task GlDraftDoesNotAffectLiveMappingsAndSameFinanceAuthorCanPublishWithoutSecondApproval(){
  await using var f=new Factory();await f.Seed();var finance=await Login(f,"finance");var employee=await Login(f,"alice");
  var input=new MasterInput("accounting","GENERAL","Cheltuieli","Expenses","{\"mainAccount\":\"TEST-GL\",\"localAccount\":\"TEST-LOCAL\",\"subAccount\":\"TEST-SUB\",\"vehicle\":false,\"repair\":false}",new(2026,1,1),null,true,"Synthetic configuration draft");
  Key(employee);Assert.Equal(HttpStatusCode.Forbidden,(await employee.PostAsJsonAsync("/api/configuration/drafts",new MasterDraftInput(input))).StatusCode);Key(finance);var saved=await finance.PostAsJsonAsync("/api/configuration/drafts",new MasterDraftInput(input));Assert.True(saved.IsSuccessStatusCode,await saved.Content.ReadAsStringAsync());var json=await saved.Content.ReadFromJsonAsync<JsonElement>();var id=json.GetProperty("id").GetGuid();
  using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Empty(await db.Masters.Where(m=>m.Kind=="accounting").ToListAsync());Assert.Equal("Draft",(await db.MasterDrafts.SingleAsync()).State);}
  Key(finance);var published=await finance.PostAsJsonAsync($"/api/configuration/drafts/{id}/publish",new VersionRequest(1,"Publish by the same authorized Finance owner"));Assert.True(published.IsSuccessStatusCode,await published.Content.ReadAsStringAsync());
  using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();var draft=await db.MasterDrafts.SingleAsync();Assert.Equal("Published",draft.State);Assert.Equal(draft.AuthorId,draft.UpdatedBy);Assert.Equal(2,draft.Version);Assert.Equal((await db.Masters.SingleAsync(m=>m.Kind=="accounting")).Id,draft.MasterId);Assert.Empty(await db.ApprovalTasks.ToListAsync());await SchemaUpgrades.Apply(db);await Assert.ThrowsAnyAsync<Exception>(()=>db.Database.ExecuteSqlRawAsync("UPDATE \"MasterDrafts\" SET \"DataJson\" = '{}'"));draft.DataJson="{}";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
  Key(finance);Assert.Equal(HttpStatusCode.Conflict,(await finance.PutAsJsonAsync($"/api/configuration/drafts/{id}",new MasterDraftInput(input,2))).StatusCode);
 }
 [Fact]public async Task InvalidDraftCannotPublishAndCancellationPreservesHistory(){
  await using var f=new Factory();await f.Seed();var finance=await Login(f,"finance");var input=new MasterInput("costCenters","CC","Centru","Cost centre","{}",new(2026,1,1),null,true,"Incomplete synthetic draft");Key(finance);var saved=await finance.PostAsJsonAsync("/api/configuration/drafts",new MasterDraftInput(input));Assert.True(saved.IsSuccessStatusCode,await saved.Content.ReadAsStringAsync());var id=(await saved.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();Key(finance);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await finance.PostAsJsonAsync($"/api/configuration/drafts/{id}/publish",new VersionRequest(1,"Incomplete ERP code must block publication"))).StatusCode);
  using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Empty(await db.Masters.ToListAsync());var draft=await db.MasterDrafts.SingleAsync();Assert.Equal("Draft",draft.State);Assert.Equal(1,draft.Version);}
  Key(finance);Assert.Equal(HttpStatusCode.OK,(await finance.PostAsJsonAsync($"/api/configuration/drafts/{id}/cancel",new VersionRequest(1,"Cancel the incomplete draft"))).StatusCode);
  using(var scope=f.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Db>();Assert.Equal("Cancelled",(await db.MasterDrafts.SingleAsync()).State);Assert.Empty(await db.Masters.ToListAsync());Assert.Single(await db.Audits.Where(a=>a.Action=="MasterDraftCancelled").ToListAsync());}
 }
}
